
const A='/assets/';
const img=(file,alt,cls='')=>`<img class="${cls}" src="${A+file}" alt="${alt}" loading="lazy">`;
const tag=(s)=>`<span class="eyebrow">${s}</span>`;
const button=(label,href)=>`<a class="btn" href="${href}">${label} ↗</a>`;
const work=[
 {name:'Clemson Experiential Learning',label:'Professional · Marketing Strategy & Storytelling',href:'#clemson',img:'campus.jpg'},
 {name:'Blue Line Technologies',label:'Professional · Brand Identity & B2B Marketing',href:'#blue-line',img:'blue-horizontal.jpg'},
 {name:'The Bean',label:'Personal Project · Brand & Social Media Strategy',href:'#the-bean',img:'bean-social.jpg'}
];
const academic=[
 {name:'Summer Fridays',subtitle:'Go-to-Market Strategy',body:'An academic go-to-market plan for a proposed SPF Lip Butter Balm launch, exploring segmentation, positioning, pricing, competitive context, distribution, and promotional channels.',skills:['Brand Strategy','Market Research','Positioning','Promotional Planning'],href:'#summer-fridays'},
 {name:'Whimsy Whips',subtitle:'Market Research & Business Strategy',body:'A research-driven custom cake and dessert shop concept for Central, SC, exploring local demographics, competitors, search trends, and location strategy.',skills:['Market Research','Location Analysis','Business Strategy'],href:'#whimsy-whips'},
 {name:'East Bower Cider Co.',subtitle:'Social Media Creative Campaign',body:'An academic campaign exploring consumer insights and social media concepts, including a Dog of the Week idea and promotional content.',skills:['Consumer Research','Social Media Strategy','Creative Campaigns']},
 {name:'BioLink Life Sciences',subtitle:'Client Collaboration & Digital Marketing',body:'Academic client collaboration involving presentation materials, LinkedIn content concepts, and digital marketing recommendations.',skills:['Content Strategy','Presentation Design','Client Collaboration'],href:'#biolink'}
];
function card(p){return `<a class="card" href="${p.href}"><div class="thumb">${img(p.img,p.name)}</div><h3>${p.name}</h3><div class="small">${p.label}</div></a>`}
function home(){return `<section class="wrap hero"><div>${tag('Marketing & Brand Strategy')}<h1><span>EMMA <i class="spark">✳</i></span><span>MADDEN</span></h1><div class="tagline">Strategic Ideas.<br><em>Creative Impact.</em></div>${button('Explore My Work','#work')}</div><div class="hero-photo">${img('portrait.jpg','Emma Madden portrait')}</div></section><section class="blush-section section"><div class="wrap"><div class="section-head"><div>${tag('01 / Portfolio')}<h2>Featured Work.</h2></div><a class="link" href="#work">Explore all work →</a></div><div class="feature"><div class="feature-copy">${tag('Professional / Featured Case Study')}<h3>Clemson<br>Experiential<br>Learning.</h3><p>Making learning by doing visible through marketing strategy, storytelling, and creative content.</p><a class="link" href="#clemson">Explore project →</a></div>${img('campus.jpg','Clemson University Tillman Hall')}</div><div class="cards">${work.map(card).join('')}<a class="card" href="#academic"><div class="thumb"><div class="empty-visual">Academic<br>Projects ✳</div></div><h3>Academic Projects</h3><div class="small">Strategy · Branding · Campaigns</div></a></div></div></section><section class="section wrap"><p class="quote serif">Strategic thinking drives the plan.<br><em>Creative storytelling</em> brings it to life.</p></section>`}
function about(){return `<section class="wrap page-intro">${tag('02 / The person behind the work')}<div class="split"><div class="prose"><h1>A little<br>about me.</h1><p class="lead"><strong>Hi, I'm Emma!</strong></p><p>I'm a creative-minded marketer with a love for brand strategy, storytelling, and bringing ideas to life.</p><p>I'm currently pursuing my M.S. in Marketing at Clemson University, where I also serve as a Marketing Graduate Assistant for Clemson Experiential Learning. With experience spanning creative agencies, higher education, and Walt Disney World, I've developed a strong foundation in social media strategy, creative storytelling, campaign development, and project management. I enjoy finding the balance between strategic thinking and creativity to build meaningful connections between brands and their audiences.</p><p>I'm especially interested in opportunities within brand strategy, creative advertising, and brand marketing, where I can bring fresh ideas and a consumer-focused perspective to the table.</p><p>Outside of marketing, you'll usually find me exploring a new coffee shop, reading a good book, or planning my next adventure.</p></div><div class="photo-stack">${img('about.jpg','Emma traveling in London')}</div></div><div class="strip">${img('travel.jpg','Travel in London')}${img('campus.jpg','Clemson campus')}${img('portrait.jpg','Emma outdoors')}</div></section>`}
function experience(){const rows=[
 ['Clemson University','Marketing Graduate Assistant · Clemson Experiential Learning','June 2026 – Present','Develop marketing strategies, digital content, and promotional materials to increase awareness of experiential learning. Collaborate with university leadership and campus partners on strategic initiatives.'],
 ['Innovated Studios','Project Coordinator','July 2025 – May 2026','Coordinated cross-functional teams, marketing campaigns, and client project workflows, managing timelines and deliverables to support successful execution.'],
 ['Walt Disney World','Guest Relations','May 2025 – July 2025','Delivered personalized guest experiences, resolved complex inquiries, and collaborated across departments to uphold Disney’s service standards.'],
 ['Walt Disney World','Disney College Program · Merchandise','January 2025 – May 2025','Supported merchandise operations and guest experiences while expanding marketing knowledge through Disney-led professional development opportunities.'],
 ['Café Moka','Supervisor & Social Media Marketing','August 2023 – December 2024','Supervised daily café operations and collaborated on social media content, seasonal promotions, and marketing initiatives to strengthen the café’s brand presence.'],
 ['Blue Line Technologies','Marketing Intern','June 2023 – August 2023','Conducted market research, competitive analysis, and customer profiling to support marketing strategy, brand awareness, and sales initiatives.'],
 ['Walt Disney World','Disney College Program · Merchandise & Trainer','August 2022 – June 2023','Delivered guest experiences and trained new Cast Members in merchandise operations, customer service, and retail procedures.']
];
const certifications=[
 ['Google','Google Analytics Certification'],
 ['HubSpot','Social Media Certificate; Content Marketing Certification'],
 ['Canva','Canva Essentials; Marketing with Canva; Graphic Design Essentials; Work Smarter with AI; Scale Creative Campaigns'],
 ['Coursera','Microsoft Project Certification']
];
return `<section class="wrap page-intro">${tag('03 / Background & Capabilities')}<div class="split"><div><h1>Experience<br>& Expertise.</h1><p class="lead">A blend of marketing, creative collaboration, and brand experiences across industries.</p></div>${img('travel.jpg','London street and travel photography')}</div></section><section class="wrap section">${tag('Where I’ve worked')}<h2>Professional Experience.</h2>${rows.map((x,i)=>`<div class="experience-row"><span class="num">0${i+1}</span><h3>${x[0]}</h3><div class="roles"><div class="role"><strong>${x[1]}</strong><div class="small">${x[2]}</div><p>${x[3]}</p></div></div></div>`).join('')}</section><section class="blush-section section"><div class="wrap"><h2>Education.</h2><p><strong>Clemson University</strong> — M.S. Marketing, expected May 2027</p><p><strong>North Carolina State University</strong> — B.S. Business Administration, Marketing, August 2024</p><p><strong>University of Oxford</strong> — Study Abroad Program, Summer 2024</p><h2 style="margin-top:55px">Certifications.</h2>${certifications.map(c=>`<p><strong>${c[0]}</strong> — ${c[1]}</p>`).join('')}<h2 style="margin-top:55px">Skills & Expertise.</h2><div class="skills">${['Social Media Strategy','Content Creation & Storytelling','Brand Strategy','Advertising','Campaign Development','Market Research','Excel','Microsoft Office','Google Workspace','Graphic Design','Project Management','Creative Thinking','Communication','Critical Thinking','Time Management','Planning & Organization'].map(x=>`<span class="pill">${x}</span>`).join('')}</div></div></section>`}
function workPage(){return `<section class="wrap page-intro">${tag('04 / Portfolio')}<h1>Work<br>Experience.</h1><p class="lead">A collection of professional and personal work where strategy meets creativity.</p></section><section class="wrap"><div class="feature"><div class="feature-copy">${tag('Featured · Professional')}<h3>Clemson Experiential Learning.</h3><p>Marketing strategy, social content, and brand storytelling.</p><a class="link" href="#clemson">View case study →</a></div>${img('campus.jpg','Tillman Hall at Clemson')}</div><div class="gallery" style="margin:55px 0">${work.slice(1).map(card).join('')}</div><div class="section-head"><div>${tag('Additional work')}<h2>Academic Projects.</h2></div><a class="link" href="#academic">View academic work →</a></div></section>`}
function academics(){return `<section class="wrap page-intro">${tag('05 / Academic Work')}<h1>Academic<br>Projects.</h1><p class="lead">Research, strategy, and creative thinking developed through coursework and client collaboration.</p></section><section class="wrap">${academic.map((p,i)=>`<article class="editorial-project"><div><span class="eyebrow">0${i+1} / Academic Project</span><h3>${p.name}</h3><strong>${p.subtitle}</strong><p>${p.body}</p><div class="skills">${p.skills.map(x=>`<span class="pill">${x}</span>`).join('')}</div>${p.href?`<p><a class="link" href="${p.href}">View case study →</a></p>`:''}</div><div class="project-visual" style="background:#faeeed;display:flex;align-items:center;justify-content:center;min-height:260px;padding:30px"><div style="text-align:center"><span class="eyebrow">ACADEMIC WORK</span><h3>${p.name}</h3><p>${p.subtitle}</p></div></div></article>`).join('')}</section>`}
function clemsonCase(){
const contentTypes=[["◎","Hands-on learning","Classrooms, labs, research and fieldwork"],["✦","Student stories","Current students and alumni"],["✳","Faculty features","Teaching and experiential learning"],["◉","International education","Study abroad and global opportunities"],["▤","Educational content","ExL types and resources"],["▦","Events & community","Workshops and campus events"]];
const alumni=[["Anna Grace Parrott","Healthcare","Internships, research and study abroad connecting classroom learning with rural healthcare.","exl-alumni-anna.jpg"],["Andrea","Education","Student teaching building classroom skills and confidence.","exl-alumni-andrea.jpg"],["Maggie","Graphic Design","UPIC and internship experiences translating creative skills into professional work.","exl-alumni-maggie.jpg"]];
return `<section class="wrap exl-hero"><a class="back" href="#work">← BACK TO WORK</a><div class="exl-hero-grid"><div>${tag('Case Study / Professional Work')}<h1>Clemson<br>Experiential<br>Learning.</h1><div class="exl-rule"></div><p class="exl-kicker">Marketing Strategy / Social Media / Brand Storytelling</p><p class="small">Marketing Graduate Assistant · June 2026–Present</p><p class="exl-statement">Bringing hands-on learning to life through strategic marketing, creative content, and storytelling.</p></div><div class="exl-hero-image">${img('campus.jpg','Clemson University campus')}</div></div></section>
<section class="wrap exl-content"><div class="exl-two"><article>${tag('01 / The Opportunity')}<h2>The Opportunity</h2><p>Clemson Experiential Learning (CU-ExL) connects students with meaningful, hands-on learning opportunities beyond the traditional classroom.</p><p>An initial marketing assessment identified opportunities to strengthen engagement, increase awareness, and help students better understand experiential learning opportunities.</p></article><article>${tag('02 / The Strategy')}<h2>The Strategy</h2><p>I developed a strategic marketing plan for the 2026–2027 academic year focused on awareness, engagement, and a more intentional approach to digital storytelling.</p><p>Instagram prioritizes student connection and understanding, while LinkedIn emphasizes alumni outcomes, faculty stories, and professional impact.</p></article></div>
<div class="exl-objectives">${tag('Strategic Objectives / 2026–2027')}<div class="exl-objective-grid"><div><span class="exl-symbol">◎</span><strong>Awareness</strong><p>Help students understand opportunities across disciplines.</p></div><div><span class="exl-symbol">↗</span><strong>Engagement</strong><p>Increase Instagram engagement rate from <b>2% to 3.5%</b>.</p></div><div><span class="exl-symbol">✳</span><strong>Growth</strong><p>Grow Instagram followers to <b>1,200+</b>.</p></div><div><span class="exl-symbol">⚑</span><strong>Participation</strong><p>Encourage students to explore and participate in ExL opportunities.</p></div></div><p class="exl-disclaimer">These are strategic targets, not achieved results.</p></div>
<div class="exl-pillars">${tag('The Content Foundation')}<h2>Three Content Pillars.</h2><div class="exl-pillars-grid"><article><span>01</span><h3>Experience in Action</h3><p>Showcase hands-on learning across classes, research, and community projects.</p></article><article><span>02</span><h3>Student Success Stories</h3><p>Make outcomes tangible through student and alumni experiences.</p></article><article><span>03</span><h3>ExL Explained</h3><p>Explain experiential learning and how to get involved.</p></article></div></div>
<section class="exl-social">${tag('03 / Strategy in Action')}<h2>Building Community<br>Through Content.</h2><div class="exl-social-grid"><div class="exl-social-copy"><p>I create and manage content for CU-ExL's Instagram and LinkedIn, using platform-specific strategies to reach and engage key audiences. The goal is to showcase experiences, tell meaningful stories, and make experiential learning easier to understand.</p><div class="exl-stats"><div><strong>958</strong><span>Instagram followers</span></div><div><strong>209</strong><span>Instagram posts</span></div></div><p class="exl-disclaimer">Account snapshot from October 22, 2026; totals are not attributed solely to my work.</p><p>On LinkedIn, storytelling focuses on alumni success, faculty expertise, and the professional value of experiential learning.</p></div><div class="exl-phone-wrap"><div class="exl-phone"><div class="exl-notch"></div>${img('exl-instagram-grid.jpg','CU-ExL Instagram grid')}</div></div><div class="exl-types">${tag('Content Types')}<ul>${contentTypes.map(t=>`<li><span class="exl-type-icon">${t[0]}</span><div><strong>${t[1]}</strong><small>${t[2]}</small></div></li>`).join('')}</ul></div></div></section>
<section class="exl-alumni">${tag('04 / Alumni Outcomes Storytelling')}<div class="exl-alumni-header"><div><h2>From Experience<br>to Opportunity.</h2><p>Through alumni spotlights, I connect former students' hands-on experiences at Clemson with their professional journeys. These stories illustrate how internships, research, student teaching, and other opportunities develop skills and shape career paths.</p></div><a class="link" href="https://www.instagram.com/clemsonexl/" target="_blank" rel="noopener">View on Instagram ↗</a></div><div class="exl-alumni-grid">${alumni.map(a=>`<article class="exl-alumni-card"><div class="exl-alumni-image">${img(a[3],a[0]+' alumni spotlight')}</div><div class="exl-alumni-copy"><span>${a[1]}</span><h3>${a[0]}</h3><p>${a[2]}</p></div></article>`).join('')}</div></section>
<section class="exl-brand">${tag('05 / Brand & Promotional Design')}<div class="exl-brand-grid"><div><h2>Brand<br>Touchpoints.</h2><p>Alongside digital content, I designed branded materials to extend CU-ExL's presence across campus and create recognizable touchpoints for students.</p></div><figure>${img('exl-business-card.png','Original CU-ExL business card')}<figcaption><strong>Business Card Design</strong><p>A consistent branded touchpoint with key contact information.</p></figcaption></figure><figure>${img('exl-sticker-sheet.png','Original CU-ExL sticker sheet')}<figcaption><strong>Promotional Sticker Sheet</strong><p>Playful designs using CU-ExL identity and Clemson-inspired visuals.</p></figcaption></figure></div></section><a class="back" href="#work">← BACK TO WORK</a></section>`;
}
function blueLineCase(){
return `<section class="wrap exl-hero bl-hero"><a class="back" href="#work">← BACK TO WORK</a><div class="exl-hero-grid"><div>${tag('Case Study / Professional Work')}<h1>Blue Line<br>Technologies.</h1><div class="exl-rule"></div><p class="exl-kicker">B2B Marketing / Brand Development / Creative Adaptation</p><p class="small">Marketing Intern · June–August 2023</p><p class="exl-statement">Supporting an established technology brand through marketing research, creative work, and anniversary branding.</p></div><div class="bl-hero-logo">${img("blue-horizontal.jpg","Blue Line Technologies horizontal 10th anniversary logo")}</div></div></section>
<section class="wrap exl-content bl-content"><div class="exl-two"><article>${tag('01 / The Opportunity')}<h2>A Milestone Worth Celebrating.</h2><p>During my marketing internship at Blue Line Technologies, I supported marketing initiatives at a B2B technology company and contributed to creative work surrounding its 10th anniversary.</p><p>The anniversary presented an opportunity to recognize a company milestone while maintaining the familiarity of its established identity.</p></article><article>${tag('02 / My Role')}<h2>Marketing Intern.</h2><p>My internship introduced me to marketing in a business-to-business environment, combining research, creative development, and support for broader marketing initiatives.</p><p>A featured project involved adapting Blue Line’s existing brand elements into two distinct anniversary logos.</p></article></div>
<div class="bl-responsibilities">${tag('Areas of Experience')}<div class="bl-responsibility-grid"><article><span>◎</span><h3>Marketing Research</h3><p>Exploring the audiences and market context behind B2B communications.</p></article><article><span>✳</span><h3>Brand Adaptation</h3><p>Working within an established identity to create commemorative designs.</p></article><article><span>↗</span><h3>Creative Support</h3><p>Contributing to marketing initiatives in a professional technology setting.</p></article></div></div>
<section class="bl-anniversary">${tag('03 / 10 Years of Blue Line')}<div class="bl-anniversary-intro"><h2>Anniversary<br>Branding.</h2><p>To celebrate Blue Line Technologies’ 10th anniversary in 2023, I adapted the company’s existing visual identity into two commemorative logo designs. One incorporated the milestone directly into the wordmark; the other used a celebratory badge format with the company’s blue and green palette. <strong>Both designs were adopted and used by Blue Line in different contexts.</strong></p></div><div class="bl-logo-grid"><figure><div class="bl-logo-image">${img('blue-horizontal.jpg','Original Blue Line Technologies horizontal 10th anniversary logo designed by Emma Madden')}</div><figcaption><h3>Horizontal Anniversary Logo</h3><p>A wordmark-led approach that integrates the milestone with Blue Line’s established identity.</p></figcaption></figure><figure><div class="bl-logo-image">${img('blue-badge.jpg','Original Blue Line Technologies 10 years commemorative badge designed by Emma Madden')}</div><figcaption><h3>Commemorative Anniversary Badge</h3><p>A badge-style composition using the brand’s blue and green with the 2013–2023 dates.</p></figcaption></figure></div></section>
<section class="bl-approach">${tag('04 / The Creative Approach')}<h2>Two Formats.<br>One Brand Identity.</h2><div class="bl-approach-grid"><article><span>01</span><h3>Respect the Existing Brand</h3><p>Retain the recognizable Blue Line name, typography, and visual character.</p></article><article><span>02</span><h3>Highlight the Milestone</h3><p>Make ten years the central message without losing brand recognition.</p></article><article><span>03</span><h3>Design for Different Uses</h3><p>Offer two distinct compositions that could serve different contexts.</p></article></div></section>
<section class="bl-takeaways">${tag('05 / Impact & Takeaways')}<div class="bl-takeaways-grid"><div><h2>Building Skills<br>for the Future.</h2><p>This internship gave me experience contributing to an established B2B brand. The anniversary project was an opportunity to practice creative adaptation rather than redesigning a brand from scratch.</p><p>Seeing both designs used by the company reinforced the importance of balancing fresh ideas with visual consistency and practical applications.</p></div><div class="bl-impact"><div><strong>02</strong><span>Anniversary logo designs</span></div><div><strong>10</strong><span>Years celebrated in 2023</span></div><p>Both designs were used by Blue Line Technologies in different contexts.</p></div></div></section><a class="back" href="#work">← BACK TO WORK</a></section>`;
}
function beanCase(){
return `<section class="wrap exl-hero bean-hero"><a class="back" href="#work">← BACK TO WORK</a><div class="exl-hero-grid"><div>${tag('Case Study / Personal Creative Project')}<h1>The Bean.</h1><div class="exl-rule"></div><p class="exl-kicker">Social Media Strategy / Creative Direction / Graphic Design</p><p class="exl-statement">A cozy coffee-shop concept designed around connection, everyday rituals, and community.</p><p class="small">Self-directed concept · Instagram campaign and promotional graphics</p></div><div class="bean-hero-image">${img('bean-social.jpg','The Bean original nine-post Instagram feed concept')}</div></div></section>
<section class="wrap exl-content bean-content"><div class="exl-two"><article>${tag('01 / The Concept')}<h2>More Than Coffee.</h2><p>The Bean is a personal coffee-shop marketing concept centered on a warm, welcoming place to study, meet friends, read, or pick up a favorite drink.</p><p>The creative direction emphasizes the familiar routines and small moments that make a neighborhood café feel like part of its community.</p></article><article>${tag('02 / The Strategy')}<h2>Community First.</h2><p>The proposed Instagram strategy aims to build brand awareness, strengthen customer loyalty, and encourage repeat visits and online engagement.</p><p>Content ideas include seasonal promotions, customer spotlights, behind-the-scenes reels, and lifestyle imagery with soft, inviting tones.</p></article></div>
<section class="bean-social">${tag('03 / Social Media Campaign')}<div class="bean-social-grid"><div><h2>A Feed That<br>Feels Like Home.</h2><p>I created a cohesive nine-post Instagram feed concept combining coffee, café interiors, reading, studying, and everyday moments. The warm, muted photography supports The Bean’s approachable, community-centered positioning.</p><div class="bean-pills"><span>Seasonal Promotions</span><span>Customer Moments</span><span>Behind the Scenes</span><span>Everyday Rituals</span></div><p class="bean-note">Concept feed — not a published campaign or measured account performance.</p></div><figure class="bean-feed">${img('bean-social.jpg','Original The Bean social media nine-post moodboard')}<figcaption>Original Instagram feed concept</figcaption></figure></div></section>
<section class="bean-creative">${tag('04 / Promotional Design')}<h2>Bringing the Brand<br>Beyond the Feed.</h2><p class="bean-creative-intro">The concept extends into seasonal menu and community event graphics, using a soft sage palette, decorative typography, and illustrated details to create a consistent café atmosphere.</p><div class="bean-creative-grid"><figure><div class="bean-art">${img('bean-menu.jpg','Original Fall Menu design for The Bean')}</div><figcaption><h3>Fall Menu</h3><p>A seasonal drinks concept featuring comforting autumn flavors and playful café illustrations.</p></figcaption></figure><figure><div class="bean-art">${img('bean-event.jpg','Original Lattes and Literature event invitation for The Bean')}</div><figcaption><h3>Lattes & Literature</h3><p>A community event invitation connecting coffee, reading, and the café’s welcoming identity. Event details are illustrative placeholders.</p></figcaption></figure></div></section>
<section class="bean-takeaways">${tag('05 / Creative Takeaways')}<div class="bean-takeaways-grid"><div><h2>Strategy Meets<br>Atmosphere.</h2><p>The Bean explores how consistent visual storytelling and community-focused content can turn a simple coffee-shop concept into a recognizable brand experience.</p><p>It demonstrates my approach to social media planning, campaign concepts, and graphic design through a cohesive creative direction.</p></div><div class="bean-logo-panel">${img('bean-logo.jpg','The Bean concept logo')}<span>Personal creative project · Concept work</span></div></div></section><a class="back" href="#work">← BACK TO WORK</a></section>`;
}
function casePage(kind){if(kind==='clemson')return clemsonCase();if(kind==='blue-line')return blueLineCase();if(kind==='the-bean')return beanCase();const blue=kind==='blue-line',bean=kind==='the-bean';
const title=blue?'Blue Line Technologies':bean?'The Bean':'Clemson Experiential Learning';
const subtitle=blue?'B2B marketing, research, and anniversary brand identity.':bean?'A coffee shop social media campaign concept centered on community, warmth, and everyday rituals.':'Connecting classroom learning to real-world experiences through strategic storytelling.';
const role=blue?'Marketing Intern':bean?'Personal Creative Project':'Marketing Graduate Assistant';
const focus=blue?'Market Research · Brand Identity':bean?'Social Media Strategy · Graphic Design':'Marketing Strategy · Content Creation · Storytelling';
const timeline=blue?'June – August 2023':bean?'Personal Portfolio Project':'June 2026 – Present';
const sections=blue?[
 ['The Opportunity','Support Blue Line Technologies’ marketing initiatives and commemorate the company’s ten-year milestone through anniversary branding.'],
 ['My Contributions','Contributed to technology market research, customer profiling, marketing initiatives, and brand identity work.'],
 ['10 Years of Blue Line','Designed two distinct anniversary logo formats that were both used by Blue Line Technologies.'],
 ['Takeaways','A professional opportunity to connect research-led marketing work with real-world creative execution.']
]:bean?[
 ['The Concept','Develop a warm, welcoming coffee shop identity centered on studying, reading, meeting friends, and community connection.'],
 ['The Strategy','Create a cohesive Instagram presence using soft imagery, seasonal promotions, customer-centered content, and behind-the-scenes storytelling.'],
 ['Creative Execution','Developed an Instagram feed concept, fall menu graphic, and a Lattes & Literature event invitation.'],
 ['Project Context','This is a personal creative concept. Designs are portfolio examples, not evidence of an operating business or published campaign.']
]:[
 ['The Opportunity','Increase awareness of hands-on learning experiences and help students, faculty, and the wider Clemson community understand their value.'],
 ['My Approach','Use student and faculty storytelling, educational content, social media strategy, and visual communication to make experiential learning approachable.'],
 ['Creative Execution','Develop Instagram and LinkedIn content, reels, graphics, spotlights, and marketing materials across multiple experiential learning initiatives.'],
 ['Results & Impact','Performance metrics and campaign examples will be added from verified analytics and original approved materials.']
];
return `<section class="wrap page-intro"><a href="#work" class="back">← BACK TO WORK</a><div class="split"><div>${tag('0'+(blue?2:bean?3:1)+' / '+(bean?'Personal Creative Project':'Professional Work'))}<h1>${title.replace(' Technologies','<br>Technologies').replace(' Experiential','<br>Experiential')}</h1><p class="lead">${subtitle}</p><div class="meta"><div><strong>ROLE</strong><span>${role}</span></div><div><strong>TIMELINE</strong><span>${timeline}</span></div><div><strong>FOCUS</strong><span>${focus}</span></div><div><strong>TYPE</strong><span>${bean?'Personal':'Professional'}</span></div></div></div><div class="photo-stack">${img(blue?'blue-horizontal.jpg':bean?'bean-social.jpg':'campus.jpg',title)}</div></div></section><section class="wrap section">${sections.map((s,i)=>`<div class="case-section"><span class="num">0${i+1}</span><h3>${s[0]}</h3><p>${s[1]}</p></div>`).join('')}${blue?`<h2 style="margin-top:65px">Anniversary Branding.</h2><div class="image-pair">${img('blue-horizontal.jpg','Horizontal Blue Line 10th anniversary logo')}${img('blue-badge.jpg','Blue Line 10 years anniversary badge logo')}</div>`:bean?`<h2 style="margin-top:65px">Creative Work.</h2><div class="image-pair">${img('bean-social.jpg','The Bean social media strategy and Instagram grid')}${img('bean-menu.jpg','The Bean seasonal menu and Lattes and Literature event graphics')}</div>`:`<div class="feature" style="margin-top:65px"><div class="feature-copy"><h3>Learning by doing.</h3><p>Featured examples and campaign analytics will be added as original materials are curated.</p></div>${img('campus.jpg','Clemson campus')}</div>`}<a class="back" href="#work">← BACK TO WORK</a></section>`}
function contact(){return `<section class="wrap contact">${tag('06 / Get in touch')}<h1>Let's make<br>something<br><em style="color:var(--orange)">meaningful.</em></h1><p class="lead">Interested in connecting about marketing, brand strategy, or creative opportunities? I'd love to hear from you.</p>${button('Email Me','mailto:emadde2@clemson.edu')}<p><a class="link" href="https://www.linkedin.com/" target="_blank" rel="noopener">LinkedIn ↗</a></p></section>`}
const pages={'home':home,'about':about,'experience':experience,'work':workPage,'academic':academics,'summer-fridays':()=>"<style>\n.academic-case{--ac-tint:#f7e7e5;--ac-accent:#d88b91;color:#292326;background:#faf7f3;font-family:\"DM Sans\",Arial,sans-serif;line-height:1.65;overflow:hidden}\n.academic-case *{box-sizing:border-box}.academic-case .ac-inner{width:min(1100px,calc(100% - 96px));margin-inline:auto}\n.academic-case h1,.academic-case h2{font-family:\"DM Serif Display\",Georgia,serif;font-weight:400;color:#90003d;line-height:1.08;letter-spacing:-.035em}\n.academic-case h1{font-size:clamp(54px,7.4vw,110px);letter-spacing:-.055em;margin:16px 0}.academic-case h2{font-size:clamp(34px,4.5vw,62px);margin:10px 0 25px}\n.academic-case p{font-size:15px;line-height:1.75}.academic-case .ac-eyebrow{font-size:11px;color:#90003d;letter-spacing:.15em;text-transform:uppercase;font-weight:700}\n.academic-case .ac-ribbon{display:flex;align-items:center;justify-content:space-between;gap:24px;padding:17px 0;border-top:3px solid var(--ac-accent);border-bottom:1px solid #e2cbd0}\n.academic-case .ac-ribbon strong{font-size:11px;letter-spacing:.16em;text-transform:uppercase;color:var(--ac-accent)}\n.academic-case .ac-ribbon span{font-size:11px;color:#78686d;text-align:right}\n.academic-case .ac-ribbon i{width:13px;height:13px;background:var(--ac-accent);display:inline-block;transform:rotate(45deg);margin-right:14px;vertical-align:middle}\n.academic-case .ac-hero{padding:90px 0 50px;background:linear-gradient(110deg,var(--ac-tint),#faf7f3 75%)}\n.academic-case .ac-hero-layout{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,.9fr);gap:clamp(28px,5vw,70px);align-items:center}\n.academic-case .ac-hero-layout:has(.ac-hero-copy:only-child){grid-template-columns:1fr}\n.academic-case .ac-hero-copy{min-width:0}.academic-case .ac-hero p{max-width:700px;font-size:17px;line-height:1.75}\n.academic-case .ac-tags{display:flex;flex-wrap:wrap;gap:10px;margin-top:25px}.academic-case .ac-tags span{border:1px solid #cfb6bb;padding:8px 13px;font-size:11px;text-transform:uppercase;letter-spacing:.09em}\n.academic-case .ac-cover{min-width:0;margin:0;padding:16px;background:var(--ac-tint);border:1px solid #ead7d8;box-shadow:16px 16px 0 #90003d0b}\n.academic-case img{display:block;width:100%;height:auto;max-width:100%;object-fit:contain}.academic-case .ac-cover figcaption{font-size:10px;letter-spacing:.08em;color:#73656b;margin-top:10px;text-transform:uppercase}\n.academic-case .ac-rule{border-top:1px solid #e2cbd0}.academic-case .ac-split{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:clamp(30px,5vw,65px);align-items:center;padding:72px 0}\n.academic-case .ac-copy{min-width:0}.academic-case .ac-copy p{max-width:510px}.academic-case .ac-visual{min-width:0;background:var(--ac-tint);padding:20px}\n.academic-case .ac-visual img{max-height:580px}.academic-case .ac-section-title{margin:65px 0 20px;padding-top:25px}.academic-case .ac-section-title p{max-width:630px}\n.academic-case .ac-gallery{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:20px;margin:32px 0 65px}\n.academic-case .ac-gallery figure{min-width:0;margin:0;background:var(--ac-tint);padding:12px}\n.academic-case .ac-gallery img{aspect-ratio:1/1;object-fit:contain}.academic-case .ac-gallery figcaption{font-size:11px;margin-top:10px;text-align:center}\n.academic-case .ac-gallery.ac-two{grid-template-columns:repeat(2,minmax(0,1fr));max-width:850px;margin-inline:auto}\n.academic-case .ac-metrics{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:16px;margin:28px 0}\n.academic-case .ac-metric{padding:24px;background:#f9e3e9}.academic-case .ac-metric strong{display:block;font:400 32px Georgia,serif;color:#90003d}.academic-case .ac-metric small{font-size:11px}\n.academic-case .ac-note{font-size:12px;color:#7c6b70;margin:35px 0 75px}\n.academic-case .ac-quote{padding:38px;background:#f6e6e6;color:#90003d;font:italic 28px Georgia,serif}\n.academic-case.ac-whimsy{--ac-accent:#d46c94;--ac-tint:#fff0f2}\n.academic-case.ac-whimsy .ac-visual,.academic-case.ac-whimsy .ac-gallery figure{background-color:#fff1f3;background-image:linear-gradient(90deg,#e5a5b626 1px,transparent 1px),linear-gradient(#e5a5b626 1px,transparent 1px);background-size:24px 24px}\n.academic-case.ac-biolink{--ac-accent:#90003d;--ac-tint:#e9f1f6}\n.academic-case.ac-biolink .ac-hero{background:#faf7f3}.academic-case.ac-biolink .ac-ribbon i{background:#f18c45}\n.academic-case.ac-biolink .ac-visual,.academic-case.ac-biolink .ac-gallery figure{border-bottom:2px solid #e7c5cb}\n@media(max-width:760px){.academic-case .ac-inner{width:calc(100% - 40px)}.academic-case .ac-hero{padding:55px 0 35px}.academic-case .ac-hero-layout,.academic-case .ac-split{grid-template-columns:minmax(0,1fr);gap:25px}.academic-case .ac-split{padding:40px 0}.academic-case .ac-cover{max-width:560px}.academic-case .ac-gallery{grid-template-columns:repeat(2,minmax(0,1fr));gap:12px}.academic-case .ac-metrics{gap:8px}.academic-case .ac-metric{padding:12px 8px}.academic-case .ac-metric strong{font-size:clamp(19px,5vw,30px)}.academic-case .ac-ribbon{align-items:flex-start;flex-direction:column;gap:4px}.academic-case .ac-ribbon span{text-align:left}}\n@media(max-width:440px){.academic-case .ac-gallery,.academic-case .ac-gallery.ac-two{grid-template-columns:1fr}.academic-case h1{font-size:clamp(51px,13vw,75px)}}\n</style><article class=\"academic-case ac-summer\"><div class=\"ac-inner\"><div class=\"ac-ribbon\"><strong><i></i>Summer Fridays · Beauty & SPF</strong><span>Original presentation visuals · Proposed product launch</span></div></div><div class=\"ac-hero\"><div class=\"ac-hero-layout\"><div class=\"ac-hero-copy\"><div class=\"ac-eyebrow\">01 / Academic Case Study · 2026</div><h1>Summer<br>Fridays.</h1><p>A proposed SPF 30 Lip Butter Balm launch—bringing together product positioning, competitive pricing, target audience insights, and an integrated promotional strategy.</p><div class=\"ac-tags\"><span>Go-to-market strategy</span><span>Market research</span><span>Product positioning</span></div></div><figure class=\"ac-cover\"><img src=\"/assets/sf-1.png\" alt=\"Original project presentation cover\" loading=\"lazy\"><figcaption>Original project cover</figcaption></figure></div></div><div class=\"ac-inner\"><div class=\"ac-split ac-rule\"><div class=\"ac-copy\"><div class=\"ac-eyebrow\">01 / The Opportunity</div><h2>Beauty meets<br>protection.</h2><p>A proposed extension of the signature Lip Butter Balm, pairing its glossy finish with broad-spectrum SPF 30.</p><p>Sun protection, made effortless.</p></div><div class=\"ac-visual\"><img src=\"/assets/sf-3.png\" alt=\"Beauty meets<br>protection.\" loading=\"lazy\"></div></div><div class=\"ac-split ac-rule\"><div class=\"ac-visual\"><img src=\"/assets/sf-5.png\" alt=\"A $2 premium.<br>Added value.\" loading=\"lazy\"></div><div class=\"ac-copy\"><div class=\"ac-eyebrow\">02 / Pricing Strategy</div><h2>A $2 premium.<br>Added value.</h2><p><strong>$26 proposed price</strong> versus <strong>$24 existing price</strong>—a modest premium for added SPF.</p><p>A perceptual map informed the competitive position.</p></div></div><div class=\"ac-section-title ac-rule\"><div class=\"ac-eyebrow\">03 / Audience & Positioning</div><h2>Built for the everyday routine.</h2><p>Targeting beauty-conscious Gen Z and younger millennial consumers who prioritize hydration, shine, protection, and convenience.</p></div><div class=\"ac-gallery \"><figure><img src=\"/assets/sf-6.png\" alt=\"Original perceptual map\" loading=\"lazy\"><figcaption>Original perceptual map</figcaption></figure><figure><img src=\"/assets/sf-7.png\" alt=\"Original market segmentation\" loading=\"lazy\"><figcaption>Original market segmentation</figcaption></figure><figure><img src=\"/assets/sf-9.png\" alt=\"Chloe · Original buyer persona\" loading=\"lazy\"><figcaption>Chloe · Original buyer persona</figcaption></figure></div><div class=\"ac-split ac-rule\"><div class=\"ac-copy\"><div class=\"ac-eyebrow\">04 / Promotional Strategy</div><h2>Your Lips,<br>Covered.</h2><p>A three-phase launch: anticipation, discovery, and repeat purchase.</p><p>Channels: social, creators, Sephora, and email.</p></div><div class=\"ac-visual\"><img src=\"/assets/sf-12.png\" alt=\"Your Lips,<br>Covered.\" loading=\"lazy\"></div></div><p class=\"ac-note\">Academic proposal; this product and campaign are not presented as launched Summer Fridays initiatives. All featured project visuals are from the original uploaded presentation.</p></div></article>",'whimsy-whips':()=>"<style>\n.academic-case{--ac-tint:#f7e7e5;--ac-accent:#d88b91;color:#292326;background:#faf7f3;font-family:\"DM Sans\",Arial,sans-serif;line-height:1.65;overflow:hidden}\n.academic-case *{box-sizing:border-box}.academic-case .ac-inner{width:min(1100px,calc(100% - 96px));margin-inline:auto}\n.academic-case h1,.academic-case h2{font-family:\"DM Serif Display\",Georgia,serif;font-weight:400;color:#90003d;line-height:1.08;letter-spacing:-.035em}\n.academic-case h1{font-size:clamp(54px,7.4vw,110px);letter-spacing:-.055em;margin:16px 0}.academic-case h2{font-size:clamp(34px,4.5vw,62px);margin:10px 0 25px}\n.academic-case p{font-size:15px;line-height:1.75}.academic-case .ac-eyebrow{font-size:11px;color:#90003d;letter-spacing:.15em;text-transform:uppercase;font-weight:700}\n.academic-case .ac-ribbon{display:flex;align-items:center;justify-content:space-between;gap:24px;padding:17px 0;border-top:3px solid var(--ac-accent);border-bottom:1px solid #e2cbd0}\n.academic-case .ac-ribbon strong{font-size:11px;letter-spacing:.16em;text-transform:uppercase;color:var(--ac-accent)}\n.academic-case .ac-ribbon span{font-size:11px;color:#78686d;text-align:right}\n.academic-case .ac-ribbon i{width:13px;height:13px;background:var(--ac-accent);display:inline-block;transform:rotate(45deg);margin-right:14px;vertical-align:middle}\n.academic-case .ac-hero{padding:90px 0 50px;background:linear-gradient(110deg,var(--ac-tint),#faf7f3 75%)}\n.academic-case .ac-hero-layout{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,.9fr);gap:clamp(28px,5vw,70px);align-items:center}\n.academic-case .ac-hero-layout:has(.ac-hero-copy:only-child){grid-template-columns:1fr}\n.academic-case .ac-hero-copy{min-width:0}.academic-case .ac-hero p{max-width:700px;font-size:17px;line-height:1.75}\n.academic-case .ac-tags{display:flex;flex-wrap:wrap;gap:10px;margin-top:25px}.academic-case .ac-tags span{border:1px solid #cfb6bb;padding:8px 13px;font-size:11px;text-transform:uppercase;letter-spacing:.09em}\n.academic-case .ac-cover{min-width:0;margin:0;padding:16px;background:var(--ac-tint);border:1px solid #ead7d8;box-shadow:16px 16px 0 #90003d0b}\n.academic-case img{display:block;width:100%;height:auto;max-width:100%;object-fit:contain}.academic-case .ac-cover figcaption{font-size:10px;letter-spacing:.08em;color:#73656b;margin-top:10px;text-transform:uppercase}\n.academic-case .ac-rule{border-top:1px solid #e2cbd0}.academic-case .ac-split{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:clamp(30px,5vw,65px);align-items:center;padding:72px 0}\n.academic-case .ac-copy{min-width:0}.academic-case .ac-copy p{max-width:510px}.academic-case .ac-visual{min-width:0;background:var(--ac-tint);padding:20px}\n.academic-case .ac-visual img{max-height:580px}.academic-case .ac-section-title{margin:65px 0 20px;padding-top:25px}.academic-case .ac-section-title p{max-width:630px}\n.academic-case .ac-gallery{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:20px;margin:32px 0 65px}\n.academic-case .ac-gallery figure{min-width:0;margin:0;background:var(--ac-tint);padding:12px}\n.academic-case .ac-gallery img{aspect-ratio:1/1;object-fit:contain}.academic-case .ac-gallery figcaption{font-size:11px;margin-top:10px;text-align:center}\n.academic-case .ac-gallery.ac-two{grid-template-columns:repeat(2,minmax(0,1fr));max-width:850px;margin-inline:auto}\n.academic-case .ac-metrics{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:16px;margin:28px 0}\n.academic-case .ac-metric{padding:24px;background:#f9e3e9}.academic-case .ac-metric strong{display:block;font:400 32px Georgia,serif;color:#90003d}.academic-case .ac-metric small{font-size:11px}\n.academic-case .ac-note{font-size:12px;color:#7c6b70;margin:35px 0 75px}\n.academic-case .ac-quote{padding:38px;background:#f6e6e6;color:#90003d;font:italic 28px Georgia,serif}\n.academic-case.ac-whimsy{--ac-accent:#d46c94;--ac-tint:#fff0f2}\n.academic-case.ac-whimsy .ac-visual,.academic-case.ac-whimsy .ac-gallery figure{background-color:#fff1f3;background-image:linear-gradient(90deg,#e5a5b626 1px,transparent 1px),linear-gradient(#e5a5b626 1px,transparent 1px);background-size:24px 24px}\n.academic-case.ac-biolink{--ac-accent:#90003d;--ac-tint:#e9f1f6}\n.academic-case.ac-biolink .ac-hero{background:#faf7f3}.academic-case.ac-biolink .ac-ribbon i{background:#f18c45}\n.academic-case.ac-biolink .ac-visual,.academic-case.ac-biolink .ac-gallery figure{border-bottom:2px solid #e7c5cb}\n@media(max-width:760px){.academic-case .ac-inner{width:calc(100% - 40px)}.academic-case .ac-hero{padding:55px 0 35px}.academic-case .ac-hero-layout,.academic-case .ac-split{grid-template-columns:minmax(0,1fr);gap:25px}.academic-case .ac-split{padding:40px 0}.academic-case .ac-cover{max-width:560px}.academic-case .ac-gallery{grid-template-columns:repeat(2,minmax(0,1fr));gap:12px}.academic-case .ac-metrics{gap:8px}.academic-case .ac-metric{padding:12px 8px}.academic-case .ac-metric strong{font-size:clamp(19px,5vw,30px)}.academic-case .ac-ribbon{align-items:flex-start;flex-direction:column;gap:4px}.academic-case .ac-ribbon span{text-align:left}}\n@media(max-width:440px){.academic-case .ac-gallery,.academic-case .ac-gallery.ac-two{grid-template-columns:1fr}.academic-case h1{font-size:clamp(51px,13vw,75px)}}\n</style><article class=\"academic-case ac-whimsy\"><div class=\"ac-inner\"><div class=\"ac-ribbon\"><strong><i></i>Whimsy Whips · Bakery concept</strong><span>Pink gingham · Local market research</span></div></div><div class=\"ac-hero\"><div class=\"ac-hero-layout\"><div class=\"ac-hero-copy\"><div class=\"ac-eyebrow\">02 / Academic Case Study · 2026</div><h1>Whimsy<br>Whips.</h1><p>A research-driven market analysis for a proposed custom cake and dessert shop in Central, South Carolina, focused on customer demand, competition, location, and discovery.</p><div class=\"ac-tags\"><span>Market analysis</span><span>Consumer research</span><span>Location strategy</span></div></div><figure class=\"ac-cover\"><img src=\"/assets/ww-1.png\" alt=\"Original project presentation cover\" loading=\"lazy\"><figcaption>Original project cover</figcaption></figure></div></div><div class=\"ac-inner\"><div class=\"ac-split ac-rule\"><div class=\"ac-copy\"><div class=\"ac-eyebrow\">01 / Research Approach</div><h2>Research before<br>the recipe.</h2><p>We assessed demand, local demographics, competitors, search interest, and location using industry and consumer data.</p><p>The insights shaped the concept and recommendations.</p></div><div class=\"ac-visual\"><img src=\"/assets/ww-3.png\" alt=\"Research before<br>the recipe.\" loading=\"lazy\"></div></div><div class=\"ac-section-title ac-rule\"><div class=\"ac-eyebrow\">02 / Local Consumer Landscape</div><h2>A community worth celebrating.</h2><p>Esri-based research evaluated the customer base within a 10-minute drive-time area.</p></div><div class=\"ac-metrics\"><div class=\"ac-metric\"><strong>39,009</strong><small>Residents</small></div><div class=\"ac-metric\"><strong>23.7</strong><small>Median age</small></div><div class=\"ac-metric\"><strong>13,775</strong><small>Households</small></div></div><div class=\"ac-gallery \"><figure><img src=\"/assets/ww-5.png\" alt=\"Original demographic research\" loading=\"lazy\"><figcaption>Original demographic research</figcaption></figure><figure><img src=\"/assets/ww-6.png\" alt=\"Original consumer profile\" loading=\"lazy\"><figcaption>Original consumer profile</figcaption></figure><figure><img src=\"/assets/ww-7.png\" alt=\"Original competitor analysis\" loading=\"lazy\"><figcaption>Original competitor analysis</figcaption></figure></div><div class=\"ac-split ac-rule\"><div class=\"ac-visual\"><img src=\"/assets/ww-10.png\" alt=\"Celebrations drive<br>the search.\" loading=\"lazy\"></div><div class=\"ac-copy\"><div class=\"ac-eyebrow\">03 / Search & Discovery</div><h2>Celebrations drive<br>the search.</h2><p>Search trends supported an occasion-led strategy: birthdays, weddings, graduations, and custom desserts.</p><p>SEO focus: location, product, and occasion.</p></div></div><div class=\"ac-split ac-rule\"><div class=\"ac-copy\"><div class=\"ac-eyebrow\">04 / Location & Recommendation</div><h2>A place for<br>sweet moments.</h2><p>Proposed location: West Main Street in Central, near Clemson and the local customer base.</p><p>Differentiators: customization, convenience, and memorable branding.</p></div><div class=\"ac-visual\"><img src=\"/assets/ww-8.png\" alt=\"A place for<br>sweet moments.\" loading=\"lazy\"></div></div><p class=\"ac-note\">Academic business concept, not an operating bakery. All research slides and images shown here come from the original uploaded Whimsy Whips presentation.</p></div></article>",'biolink':()=>"<style>\n.academic-case{--ac-tint:#f7e7e5;--ac-accent:#d88b91;color:#292326;background:#faf7f3;font-family:\"DM Sans\",Arial,sans-serif;line-height:1.65;overflow:hidden}\n.academic-case *{box-sizing:border-box}.academic-case .ac-inner{width:min(1100px,calc(100% - 96px));margin-inline:auto}\n.academic-case h1,.academic-case h2{font-family:\"DM Serif Display\",Georgia,serif;font-weight:400;color:#90003d;line-height:1.08;letter-spacing:-.035em}\n.academic-case h1{font-size:clamp(54px,7.4vw,110px);letter-spacing:-.055em;margin:16px 0}.academic-case h2{font-size:clamp(34px,4.5vw,62px);margin:10px 0 25px}\n.academic-case p{font-size:15px;line-height:1.75}.academic-case .ac-eyebrow{font-size:11px;color:#90003d;letter-spacing:.15em;text-transform:uppercase;font-weight:700}\n.academic-case .ac-ribbon{display:flex;align-items:center;justify-content:space-between;gap:24px;padding:17px 0;border-top:3px solid var(--ac-accent);border-bottom:1px solid #e2cbd0}\n.academic-case .ac-ribbon strong{font-size:11px;letter-spacing:.16em;text-transform:uppercase;color:var(--ac-accent)}\n.academic-case .ac-ribbon span{font-size:11px;color:#78686d;text-align:right}\n.academic-case .ac-ribbon i{width:13px;height:13px;background:var(--ac-accent);display:inline-block;transform:rotate(45deg);margin-right:14px;vertical-align:middle}\n.academic-case .ac-hero{padding:90px 0 50px;background:linear-gradient(110deg,var(--ac-tint),#faf7f3 75%)}\n.academic-case .ac-hero-layout{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,.9fr);gap:clamp(28px,5vw,70px);align-items:center}\n.academic-case .ac-hero-layout:has(.ac-hero-copy:only-child){grid-template-columns:1fr}\n.academic-case .ac-hero-copy{min-width:0}.academic-case .ac-hero p{max-width:700px;font-size:17px;line-height:1.75}\n.academic-case .ac-tags{display:flex;flex-wrap:wrap;gap:10px;margin-top:25px}.academic-case .ac-tags span{border:1px solid #cfb6bb;padding:8px 13px;font-size:11px;text-transform:uppercase;letter-spacing:.09em}\n.academic-case .ac-cover{min-width:0;margin:0;padding:16px;background:var(--ac-tint);border:1px solid #ead7d8;box-shadow:16px 16px 0 #90003d0b}\n.academic-case img{display:block;width:100%;height:auto;max-width:100%;object-fit:contain}.academic-case .ac-cover figcaption{font-size:10px;letter-spacing:.08em;color:#73656b;margin-top:10px;text-transform:uppercase}\n.academic-case .ac-rule{border-top:1px solid #e2cbd0}.academic-case .ac-split{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:clamp(30px,5vw,65px);align-items:center;padding:72px 0}\n.academic-case .ac-copy{min-width:0}.academic-case .ac-copy p{max-width:510px}.academic-case .ac-visual{min-width:0;background:var(--ac-tint);padding:20px}\n.academic-case .ac-visual img{max-height:580px}.academic-case .ac-section-title{margin:65px 0 20px;padding-top:25px}.academic-case .ac-section-title p{max-width:630px}\n.academic-case .ac-gallery{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:20px;margin:32px 0 65px}\n.academic-case .ac-gallery figure{min-width:0;margin:0;background:var(--ac-tint);padding:12px}\n.academic-case .ac-gallery img{aspect-ratio:1/1;object-fit:contain}.academic-case .ac-gallery figcaption{font-size:11px;margin-top:10px;text-align:center}\n.academic-case .ac-gallery.ac-two{grid-template-columns:repeat(2,minmax(0,1fr));max-width:850px;margin-inline:auto}\n.academic-case .ac-metrics{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:16px;margin:28px 0}\n.academic-case .ac-metric{padding:24px;background:#f9e3e9}.academic-case .ac-metric strong{display:block;font:400 32px Georgia,serif;color:#90003d}.academic-case .ac-metric small{font-size:11px}\n.academic-case .ac-note{font-size:12px;color:#7c6b70;margin:35px 0 75px}\n.academic-case .ac-quote{padding:38px;background:#f6e6e6;color:#90003d;font:italic 28px Georgia,serif}\n.academic-case.ac-whimsy{--ac-accent:#d46c94;--ac-tint:#fff0f2}\n.academic-case.ac-whimsy .ac-visual,.academic-case.ac-whimsy .ac-gallery figure{background-color:#fff1f3;background-image:linear-gradient(90deg,#e5a5b626 1px,transparent 1px),linear-gradient(#e5a5b626 1px,transparent 1px);background-size:24px 24px}\n.academic-case.ac-biolink{--ac-accent:#90003d;--ac-tint:#e9f1f6}\n.academic-case.ac-biolink .ac-hero{background:#faf7f3}.academic-case.ac-biolink .ac-ribbon i{background:#f18c45}\n.academic-case.ac-biolink .ac-visual,.academic-case.ac-biolink .ac-gallery figure{border-bottom:2px solid #e7c5cb}\n@media(max-width:760px){.academic-case .ac-inner{width:calc(100% - 40px)}.academic-case .ac-hero{padding:55px 0 35px}.academic-case .ac-hero-layout,.academic-case .ac-split{grid-template-columns:minmax(0,1fr);gap:25px}.academic-case .ac-split{padding:40px 0}.academic-case .ac-cover{max-width:560px}.academic-case .ac-gallery{grid-template-columns:repeat(2,minmax(0,1fr));gap:12px}.academic-case .ac-metrics{gap:8px}.academic-case .ac-metric{padding:12px 8px}.academic-case .ac-metric strong{font-size:clamp(19px,5vw,30px)}.academic-case .ac-ribbon{align-items:flex-start;flex-direction:column;gap:4px}.academic-case .ac-ribbon span{text-align:left}}\n@media(max-width:440px){.academic-case .ac-gallery,.academic-case .ac-gallery.ac-two{grid-template-columns:1fr}.academic-case h1{font-size:clamp(51px,13vw,75px)}}\n</style><article class=\"academic-case ac-biolink\"><div class=\"ac-inner\"><div class=\"ac-ribbon\"><strong><i></i>BioLink Life Sciences · B2B</strong><span>Scientific services · Original creative deliverables</span></div></div><div class=\"ac-hero\"><div class=\"ac-hero-layout\"><div class=\"ac-hero-copy\"><div class=\"ac-eyebrow\">03 / NC State Client Practicum · Fall 2023</div><h1>BioLink<br>Life Sciences.</h1><p>A real-client collaboration translating technical pharmaceutical services into clearer brand messaging, presentation materials, and social content concepts.</p><div class=\"ac-tags\"><span>B2B marketing</span><span>Brand messaging</span><span>Content design</span></div></div></div></div><div class=\"ac-inner\"><div class=\"ac-split ac-rule\"><div class=\"ac-copy\"><div class=\"ac-eyebrow\">01 / The Challenge</div><h2>Connecting science<br>to solutions.</h2><p>The challenge: communicate specialized pharmaceutical services clearly.</p><p>Our approach: simplify technical messaging through social content and presentation design.</p></div><div class=\"ac-visual\"><img src=\"/assets/BioLink%20Mission(1).png\" alt=\"Connecting science<br>to solutions.\" loading=\"lazy\"></div></div><div class=\"ac-section-title ac-rule\"><div class=\"ac-eyebrow\">02 / Original Creative Deliverables</div><h2>Designed to communicate.</h2><p>Original project graphics highlighting BioLink's mission and services.</p></div><div class=\"ac-gallery ac-two\"><figure><img src=\"/assets/BioLink%20Post%20Oct%2016(1).png\" alt=\"Original FTE Services creative\" loading=\"lazy\"><figcaption>Original FTE Services creative</figcaption></figure><figure><img src=\"/assets/BioLink%20Post%20Sept%2018(1).png\" alt=\"Six-service overview\" loading=\"lazy\"><figcaption>Six-service overview</figcaption></figure></div><div class=\"ac-section-title ac-rule\"><div class=\"ac-eyebrow\">03 / Slogan Exploration</div><h2>Finding the right words.</h2><p>Two selected slogan concepts exploring BioLink's expertise and purpose.</p></div><div class=\"ac-gallery ac-two\"><figure><img src=\"/assets/BioLink%20Slogan-2(1).png\" alt=\"Transitioning Ideas into Customer Solutions\" loading=\"lazy\"><figcaption>Transitioning Ideas into Customer Solutions</figcaption></figure><figure><img src=\"/assets/BioLink%20Slogan-3(1).png\" alt=\"Connecting Science to Solutions\" loading=\"lazy\"><figcaption>Connecting Science to Solutions</figcaption></figure></div><div class=\"ac-split ac-rule\"><div class=\"ac-copy\"><div class=\"ac-eyebrow\">04 / The Takeaway</div><h2>Complex work.<br>Clear storytelling.</h2><p>This collaboration strengthened my ability to turn technical subject matter into accessible B2B storytelling.</p></div><div class=\"ac-quote\">“Connecting Science to Solutions.”</div></div><p class=\"ac-note\">Student team practicum project. Creative concepts and social graphics are original uploaded materials; publication or client adoption is not implied.</p></div></article>",'clemson':()=>casePage('clemson'),'blue-line':()=>casePage('blue-line'),'the-bean':()=>casePage('the-bean'),'contact':contact};
function render(){const route=location.hash.slice(1)||'home';document.getElementById('app').innerHTML=(pages[route]||home)();document.title=(route==='home'?'Emma Madden':(route.replace(/-/g,' ').replace(/\b\w/g,c=>c.toUpperCase())+' | Emma Madden'));document.querySelectorAll('#nav a').forEach(a=>a.classList.toggle('active',a.hash==='#'+route));document.getElementById('nav').classList.remove('open');document.getElementById('menu-toggle').setAttribute('aria-expanded','false');window.scrollTo({top:0,behavior:'instant'})}
window.addEventListener('hashchange',render);document.getElementById('menu-toggle').onclick=()=>{const nav=document.getElementById('nav');const open=nav.classList.toggle('open');document.getElementById('menu-toggle').setAttribute('aria-expanded',String(open))};document.getElementById('year').textContent=new Date().getFullYear();render();
